 alts: [['timeline', 'Keď preberáte priebeh vojny a jej koniec.'], ['ttable', 'Keď porovnávate život na fronte a v zázemí.'], ['mind', 'Keď zhŕňate celé obdobie.']],
 std: ['S1079', 'S1080', 'S1081', 'S1083', 'S5220', 'S5221'],
 method: { goals: ['Žiak rozlíši dlhodobé príčiny a bezprostrednú zámienku vojny.', 'Žiak zoradí kľúčové medzníky vojny.', 'Žiak porovná život na fronte a v zázemí.'],
  plan: [['5 min', 'Otázka: Môže jeden atentát spustiť svetovú vojnu?'], ['15 min', 'Rybia kosť príčin.'], ['15 min', 'Časová os a práca s listom vojaka z frontu.'], ['10 min', 'Diskusia o dôsledkoch pre Slovensko.']],
  ask: ['Prečo sa do vojny zapojilo toľko štátov?', 'Čo vojna priniesla Slovákom?'] },
 guide: { primer: 'Pred vojnou sa európske veľmoci predbiehali v zbrojení a v boji o kolónie a vytvorili dva súperiace bloky. Zámienkou bol atentát na rakúsko-uhorského následníka trónu Františka Ferdinanda v Sarajeve 28. júna 1914. Vďaka spojenectvám sa lokálny spor rýchlo zmenil na svetovú vojnu. Boje skončili prímerím 11. novembra 1918. Rakúsko-Uhorsko sa rozpadlo a vznikli nástupnícke štáty vrátane Československa. Mierové zmluvy sa podpísali v rokoch 1919 a 1920.',
  steps: [
   { time: '5 min', do: 'Napíšte na tabuľu: 28. jún 1914, Sarajevo.', say: 'Stačí jeden výstrel na to, aby sa rozpútala vojna po celom svete?', check: 'Žiaci tušia, že musia existovať aj iné príčiny.' },
   { time: '15 min', do: 'Doplňte rybiu kosť. Zámienku zakreslite oddelene od dlhodobých príčin.', say: 'Čo by sa stalo, keby neexistovali spojenecké zmluvy?', check: 'Žiaci rozlíšia príčinu a zámienku.' },
   { time: '15 min', do: 'Zoraďte medzníky na časovej osi a prečítajte úryvok z listu vojaka.', check: 'Žiaci opíšu podmienky v zákopoch.' },
   { time: '10 min', do: 'Diskusia o dôsledkoch: vznik Československa a nové hranice.', check: 'Každý uvedie jeden dôsledok vojny.' }],
  traps: [['Atentát bol hlavnou príčinou vojny.', 'Atentát bol len zámienka, príčiny boli dlhodobé.'], ['Taliansko bojovalo celý čas po boku Nemecka.', 'Taliansko bolo pred vojnou v Trojspolku, v roku 1914 ostalo neutrálne a v roku 1915 vstúpilo do vojny na strane Dohody.'], ['Prímerie a mier sú to isté.', 'Prímerie 11. 11. 1918 zastavilo boje. Mier upravili až zmluvy uzavreté v rokoch 1919 a 1920.'], ['Vojna sa odohrávala len na západe.', 'Boje prebiehali aj na východnom, talianskom a balkánskom fronte.']],
  qa: [['Prečo sa volá svetová?', 'Zapojili sa do nej štáty z viacerých kontinentov a bojovalo sa aj v kolóniách a na moriach.'], ['Kto boli légie?', 'Dobrovoľnícke jednotky Čechov a Slovákov, ktoré bojovali na strane Dohody za samostatný štát.']] },
