  plan: [['5 min', 'Otázka: Čo všetko pre nás robí domov?'], ['15 min', 'Myšlienková mapa funkcií rodiny.'], ['15 min', 'Tabuľka práv a povinností, práca v skupinách.'], ['10 min', 'Reflexia: ako môžem prispieť ja?']],
